<script>export let data; export let inspect=()=>{}; $: cells=(data.cells||[]).reduce((m,c)=>{m[`${c.entityId}|${c.dimensionId}`]=c.value;return m;},{}); const value=(v)=>typeof v==='object'?JSON.stringify(v):String(v??'—');</script>
<div class="table-wrap" data-renderer="matrix-profile"><table><caption class="sr-only">Comparaison des éléments selon les dimensions visibles</caption><thead><tr><th>Élément</th>{#each data.columns || [] as col}<th>{col.label}{#if col.unit}<small> {col.unit}</small>{/if}</th>{/each}</tr></thead><tbody>{#each data.rows || [] as row}<tr><th><button class="text-button" on:click={()=>inspect(row.id)}>{row.label}</button></th>{#each data.columns || [] as col}<td>{value(cells[`${row.id}|${col.id}`])}</td>{/each}</tr>{:else}<tr><td>Aucune dimension visible.</td></tr>{/each}</tbody></table></div>
